import{g9 as s,g8 as e,ga as o}from"./index-CT-h-X-A.js";import{S as a}from"./shared-Crjz4w_p.js";const n={"bajo-n1-l01":s(o("n1-l01","teoria"),e("Siéntate derecho, con el bajo apoyado en tu pierna y el mástil un poco inclinado hacia arriba. Si tocas de pie, ajusta la correa para que el bajo quede más o menos a la misma altura que sentado.","Los dedos de la mano izquierda se numeran: 1 índice, 2 medio, 3 anular y 4 meñique. Presiona con la yema, justo detrás del traste, y deja el pulgar relajado detrás del mástil, más o menos a la altura del dedo medio.","En los primeros trastes, una forma común es usar un dedo por traste: el dedo 1 en el traste 1, el 2 en el 2, y así. Así la mano se mueve poco.","> Si una nota zumba, acerca el dedo al traste o presiona un poco más.","> Hombros y muñecas relajados: si algo duele, para y descansa."),o("n1-l01","lectura"),e("La altura nos dice si un sonido es agudo o grave. El bajo es uno de los instrumentos más graves de una banda: su trabajo es dar la base que sostiene a los demás.","En el bajo, la cuerda más gruesa (4ª, Mi) es la más grave y la más delgada (1ª, Sol) la más aguda. En una misma cuerda, mientras más cerca del cuerpo presionas, más aguda es la nota.","> Toca la 4ª cuerda al aire y luego la 1ª: escucha qué tan diferente suenan.")),"bajo-n1-l02":s(e('Todo sonido tiene cuatro propiedades: altura (agudo o grave), duración (largo o corto), intensidad (fuerte o suave) y timbre (el "color" que nos permite distinguir un bajo de una guitarra o de una voz).',"En el bajo controlas las cuatro: qué nota tocas, cuánto la dejas sonar, con cuánta fuerza pulsas y en qué parte de la cuerda lo haces (cerca del puente suena más brillante; cerca del mástil, más redondo).","> Toca la misma nota cerca del puente y luego cerca del mástil: escucha cómo cambia el timbre."),o("n1-l02","practica"),o("n1-l02","lectura"),o("n1-l02","oido")),"bajo-n1-l03":s(e("La tablatura (TAB) para bajo tiene 4 líneas, una por cada cuerda. La línea de arriba es la 1ª cuerda (Sol, la más delgada) y la de abajo es la 4ª cuerda (Mi, la más gruesa).","Los números indican el traste que debes presionar. El 0 significa cuerda al aire (sin presionar).",`TAB:
G|---------------|
D|---------------|
A|-------0--2--3-|
E|-0--1-----------|`,"> En el ejemplo: Mi al aire, traste 1 de la 4ª cuerda, y luego La al aire, traste 2 y traste 3 de la 3ª cuerda."),e("Toca despacio las líneas en TAB que te dé tu maestro, una nota a la vez y con metrónomo lento.","Primero ubica la cuerda, luego el traste, y después pulsa. Deja sonar cada nota completa antes de pasar a la siguiente.",'> Di en voz alta "cuerda 3, traste 2" antes de tocar: así tu mano y tu cabeza aprenden juntas.'),o("n1-l03","lectura"),e("En el bajo, la misma nota se puede tocar en dos lugares. Por ejemplo, el traste 5 de la 4ª cuerda (La) suena igual que la 3ª cuerda al aire.","Escucha las dos versiones: es la misma nota, aunque el timbre cambia un poquito (la cuerda al aire suena más abierta).","> Toca el traste 5 de la 4ª cuerda y luego la 3ª al aire. ¿Suenan igual?")),"bajo-n1-l04":s(e("El bajo une el ritmo con la armonía. Toca casi siempre las notas más graves de los acordes y lo hace en sincronía con la batería.","Cuando el bajo toca la nota principal de un acorde (la fundamental), la banda suena firme. Por eso a veces un bajo sencillo pero bien a tiempo es lo que más ayuda a una canción.","> Escucha una canción que te guste y trata de seguir solo el bajo."),e("Una técnica muy común para tocar bajo eléctrico es pulsar alternando los dedos índice (i) y medio (m) de la mano derecha: i-m-i-m.","Apoya el pulgar en la pastilla o en la 4ª cuerda. Pulsa la cuerda jalándola hacia ti y deja que el dedo termine apoyado en la cuerda de arriba (pulsación apoyada).","> Practica i-m-i-m en una cuerda al aire con metrónomo, buscando que las dos notas suenen igual de fuerte."),e("El bajo se escribe en clave de Fa. Sus dos puntos rodean la 4ª línea del pentagrama e indican que en esa línea va la nota Fa.","A partir de esa línea puedes encontrar las demás: en el espacio de arriba va Sol y en el de abajo va Mi.","Dato útil: el bajo suena una octava más grave de lo que se escribe; así se evitan muchas líneas adicionales.","> Líneas de la clave de Fa (de abajo hacia arriba): Sol, Si, Re, Fa, La. Espacios: La, Do, Mi, Sol."),e('En muchas canciones el bajo está "escondido" debajo de todo. Escucha la parte más grave: es esa nota profunda que acompaña al bombo de la batería.',"Con audífonos es más fácil reconocerlo.","> Escucha una canción y tararea solo la parte del bajo.")),"bajo-n1-l05":s(e("Las notas musicales son siete: Do, Re, Mi, Fa, Sol, La y Si. Después de Si vuelve a empezar Do, pero más agudo.","En el pentagrama, la posición de la nota (en qué línea o espacio está) te dice qué nota es. La figura (su forma) te dice cuánto dura.","> Repite las notas hacia arriba y hacia abajo hasta que te salgan sin pensar."),e("Las cuerdas al aire del bajo son, de la más grave a la más aguda: Mi (4ª), La (3ª), Re (2ª) y Sol (1ª).","Tan importante como tocar es apagar: cuando termines una nota, detén la cuerda tocándola suavemente con un dedo libre. Así el bajo suena limpio.","> Toca una cuerda al aire 4 tiempos y apágala exactamente en el tiempo 1 siguiente."),e("En la 4ª cuerda: Mi al aire, Fa en el traste 1 y Sol en el traste 3.","En el pentagrama (clave de Fa), el Mi de la cuerda al aire se escribe en la primera línea adicional por debajo del pentagrama; Fa va en el espacio de abajo del pentagrama y Sol en la 1ª línea.","> Toca Mi-Fa-Sol-Fa-Mi diciendo el nombre de cada nota."),o("n1-l04","oido")),"bajo-n1-l06":s(o("n1-l05","teoria"),e("La fundamental es la nota que le da nombre al acorde: en el acorde de Do, la fundamental es Do.",'Un buen primer paso es tocar la fundamental de cada acorde en negras (una nota por tiempo), contando "1, 2, 3, 4".',"> Lo más importante aquí es la constancia: que todas las negras duren lo mismo."),o("n1-l05","lectura"),o("n1-l05","oido")),"bajo-n1-l07":s(o("n1-l08","teoria"),e("Cuando veas los acordes de una canción en cifrado (por ejemplo, C - G - Am - F), toca la fundamental de cada uno: Do, Sol, La y Fa.","Busca esas notas en las cuerdas 4 y 3 para mover poco la mano.","> Practica primero los cambios sin metrónomo y después con metrónomo lento."),e("En la 3ª cuerda: La al aire, Si en el traste 2 y Do en el traste 3.","En clave de Fa, La va en el 1er espacio, Si en la 2ª línea y Do en el 2º espacio.","> Toca La-Si-Do-Si-La diciendo el nombre de cada nota."),o("n1-l08","oido")),"bajo-n1-l08":s(o("n1-l09","teoria"),e("Llegó el momento de tocar tu primera canción completa. Tu maestro te dará la línea de bajo y la pista.","Primero aprende cada parte por separado (verso, coro). Después únelas con metrónomo y, al final, toca sobre la pista.","> Si te pierdes, no te detengas: escucha la batería y vuelve a entrar en el siguiente tiempo 1."),o("n1-l09","lectura"),o("n1-l09","oido")),"bajo-n1-l09":s(e("En la batería, el bombo es el tambor más grave y la tarola (caja) es la que suena seca y fuerte, normalmente en los tiempos 2 y 4.","El bajo y el bombo forman juntos la base de la canción. Cuando el bajo toca sus notas al mismo tiempo que el bombo, la banda suena compacta.","> En muchas canciones de rock y pop el bombo cae en los tiempos 1 y 3."),e("Practica con un ritmo de batería sencillo: toca la fundamental cada vez que suene el bombo.","Escucha con atención: tu nota y el bombo deben sonar como un solo golpe.","> Usa el metrónomo o una pista de batería a 70-80 BPM para empezar."),e("En la 2ª cuerda: Re al aire, Mi en el traste 2 y Fa en el traste 3.","En clave de Fa, Re va en la 3ª línea (la de en medio), Mi en el 3er espacio y Fa en la 4ª línea, la que marcan los puntos de la clave.","> Toca Re-Mi-Fa-Mi-Re diciendo el nombre de cada nota."),e('El bombo suena grave y "redondo"; la tarola suena aguda y seca, como un chasquido.','Escucha un ritmo de batería y di "bum" en cada bombo y "pa" en cada tarola.',"> Bum-pa-bum-pa: así suenan muchos ritmos de rock.")),"bajo-n1-l10":s(e("El semitono es la distancia más pequeña entre dos notas en el bajo: un traste. El tono equivale a dos semitonos: dos trastes.","Entre las notas naturales hay un tono, excepto entre Mi-Fa y Si-Do, donde hay solo un semitono.","> Do-Re = tono (2 trastes). Mi-Fa = semitono (1 traste)."),e("La escala cromática avanza de semitono en semitono: traste por traste.","El ejercicio 1-2-3-4 consiste en tocar los trastes 1, 2, 3 y 4 de una cuerda con los dedos 1, 2, 3 y 4. Pasa por todas las cuerdas y regresa.","> Hazlo lento, con metrónomo, y deja cada dedo apoyado mientras tocas el siguiente si te es cómodo."),e("El sostenido (♯) sube una nota un semitono; el bemol (♭) la baja un semitono. Por ejemplo, Fa♯ está un traste después de Fa.","Una misma nota puede tener dos nombres: Do♯ y Re♭ suenan igual. En la partitura, una alteración vale para todo el compás."),e('Un semitono suena muy "pegadito" y tenso; un tono suena un poco más abierto.',"> Toca traste 1 y 2 (semitono) y luego traste 1 y 3 (tono) en la misma cuerda, y compara.")),"bajo-n1-l11":s(e("La octava es la misma nota, pero más aguda o más grave. Si una nota vibra el doble de rápido que otra, está una octava arriba.","En el bajo hay una figura muy útil: la octava de una nota está dos cuerdas más arriba (hacia las cuerdas delgadas) y dos trastes más adelante.","> Ejemplo: Sol en el traste 3 de la 4ª cuerda → su octava está en el traste 5 de la 2ª cuerda."),e("Una línea de bajo clásica alterna la fundamental y su octava: grave-agudo-grave-agudo.","Usa el dedo 1 para la fundamental y el 3 o el 4 para la octava, sin mover la mano.","> Practica fundamental-octava en corcheas con los acordes de tu canción."),e("En la 1ª cuerda: Sol al aire, La en el traste 2 y Si en el traste 4.","En clave de Fa, Sol va en el 4º espacio, La en la 5ª línea y Si en el espacio de arriba del pentagrama.","> Toca Sol-La-Si-La-Sol diciendo el nombre de cada nota."),e('Dos notas a una octava de distancia suenan "iguales pero en otra altura": se mezclan muy bien.',"> Toca una nota y su octava, una después de otra y luego juntas. ¿Escuchas cómo se funden?")),"bajo-n1-l12":s(e("Partes principales del bajo: cabeza (clavijero con clavijas), cejuela, mástil con trastes, cuerpo, pastillas, controles (volumen y tono) y puente.","Cuídalo: guárdalo en su funda, límpialo con un paño seco después de tocar, no lo dejes al sol ni cerca de fuentes de calor y lávate las manos antes de tocar.","> Limpiar las cuerdas después de tocar las hace durar más."),e("Cambia una cuerda a la vez para que el mástil no pierda tensión de golpe. Pasa la cuerda por el puente, llévala a su clavija y dale unas vueltas hacia abajo.","Al terminar, afina con el afinador de la app y repite: las cuerdas nuevas se estiran y se desafinan varias veces al principio.","> Si no te sientes con confianza, pídele a tu maestro que te acompañe la primera vez."),e("Repaso: lee una línea de 8 compases con las notas que ya conoces en clave de Fa.","Antes de tocar, revisa la clave, el compás y las figuras. Luego di los nombres de las notas en ritmo y, al final, tócala.","> Marca con lápiz las notas que se te dificulten."),e("Puedes afinar comparando cuerdas: el traste 5 de una cuerda suena igual que la siguiente cuerda al aire (por ejemplo, el traste 5 de la 4ª cuerda suena igual que la 3ª al aire).",'Cuando dos notas están casi afinadas, escucharás una especie de "vibración" (batimiento). Mientras más lenta, más cerca estás de la afinación.',"> En el bajo también puedes comparar armónicos: el armónico del traste 5 de una cuerda suena igual que el del traste 7 de la siguiente más aguda (por ejemplo, traste 5 de la 4ª cuerda y traste 7 de la 3ª: los dos son La)."))},r={"bajo-n2-l01":{status:"borrador",generated:!0,sections:{teoria:a.s132,practica:{paragraphs:["La línea de bajo más básica alterna la fundamental del acorde (la nota que le da nombre) con su quinta. En Do mayor: Do y Sol; en La menor: La y Mi.","En el bajo, la quinta está dos trastes arriba en la cuerda siguiente más aguda: si tocas Do en el traste 3 de la 3ª cuerda (La), su quinta (Sol) está en el traste 5 de la 2ª cuerda (Re). La quinta grave está en el mismo traste de la cuerda más grave.",'Es la base del country, el pop y el rock: sencilla, firme y siempre "correcta".'],tips:["Toca fundamental en los tiempos 1 y 3, y quinta en 2 y 4."],tab:`G|-----------|
D|---5---5---|
A|-3---3---3-|
E|-----------|`},lectura:a.s002,oido:a.s001}},"bajo-n2-l02":{status:"borrador",generated:!0,sections:{teoria:a.s006,practica:{paragraphs:["En el bajo puedes tocar la escala mayor completa sin mover la mano usando un dedo por traste. En Do mayor, empieza con el dedo 2 en el traste 3 de la 3ª cuerda (Do).","Digitación: cuerda La: 3-5 (dedos 2 y 4); cuerda Re: 2-3-5 (dedos 1-2-4); cuerda Sol: 2-4-5 (dedos 1-3-4). La misma figura sirve para cualquier tonalidad moviéndola por el mástil."],tips:["Di el nombre de cada nota al tocarla: Do–Re–Mi–Fa–Sol–La–Si–Do."],tab:`G|-----------2-4-5-|
D|-----2-3-5-------|
A|-3-5-------------|`},lectura:{paragraphs:["El bajo se lee en clave de Fa (en cuarta línea): la cuarta línea del pentagrama es Fa. Las líneas, de abajo hacia arriba, son Sol–Si–Re–Fa–La; los espacios, La–Do–Mi–Sol.","La escala de Do mayor empieza en el segundo espacio (Do) y sube hasta el Do de arriba del pentagrama. El bajo suena una octava más grave de lo escrito."],tips:['Memoriza las líneas con una frase: "Sol Si Re Fa La" y los espacios "La Do Mi Sol".']},oido:a.s008}},"bajo-n2-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['El bajo eléctrico nació en 1951 con el Fender Precision Bass. Antes, el bajo de las bandas era el contrabajo, grande y difícil de amplificar. El Precision ("preciso") tenía trastes, lo que facilitaba afinar las notas.',"En 1960 llegó el Jazz Bass, con dos pastillas y un sonido más brillante. Desde entonces el bajo ha sido central en el rock, el funk, el soul, el reggae y casi toda la música popular.","Bajistas como James Jamerson (Motown), Paul McCartney, Jaco Pastorius y Flea cambiaron la forma de tocarlo."],tips:["Escucha a James Jamerson en canciones de Motown: casi todo lo hacía con un solo dedo."]},practica:{paragraphs:["Tocar el bajo con plumilla da un ataque más definido y brillante, ideal para rock, punk y metal. Usa una plumilla gruesa (1 mm o más) y sostenla como en la guitarra.","Practica con golpes hacia abajo (downpicking) para un sonido parejo y agresivo, y con púa alternada para velocidad. Apoya ligeramente la palma cerca del puente para controlar el sonido."],tips:["Alterna 4 compases con dedos y 4 con plumilla para escuchar la diferencia."]},lectura:a.s133,oido:{paragraphs:['Los dedos dan un sonido más redondo y cálido; la plumilla, un ataque más marcado y brillante, con un "clic" al inicio de cada nota.',"Escucha fragmentos y decide si el bajista toca con dedos o con plumilla."],tips:["El ataque es la pista principal: fíjate en el inicio de cada nota."]}}},"bajo-n2-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['El volumen controla cuánta señal sale del bajo. El tono recorta agudos: abierto suena brillante, cerrado suena más grave y "vintage".',"Si tu bajo tiene dos pastillas (como un Jazz Bass), cada una tiene su volumen: la del mástil suena gorda y redonda; la del puente, más definida y con más medios. Mezclarlas da un sonido equilibrado."],tips:["Prueba la misma línea con cada pastilla sola y con ambas."]},practica:{paragraphs:["En el bajo, las cuerdas que no tocas pueden sonar solas por vibración. Para evitarlo se apagan con las dos manos: la mano izquierda apoya dedos sueltos sobre las cuerdas y la derecha apoya el pulgar o los dedos que no pulsan.",'Una técnica útil es el "pulgar flotante": el pulgar derecho se mueve con la mano y descansa sobre las cuerdas graves que no se tocan.'],tips:["Toca una línea y escucha: si suena alguna cuerda que no tocaste, apágala."]},lectura:a.s134,oido:a.s005}},"bajo-n2-l05":{status:"borrador",generated:!0,sections:{teoria:a.s009,practica:{paragraphs:["Un arpegio de tríada en el bajo toca fundamental, tercera y quinta. Para Do mayor (Do–Mi–Sol): traste 3 de La (Do), traste 2 de Re (Mi) y traste 5 de Re (Sol).","Para La menor (La–Do–Mi): traste 5 de Mi (La), traste 3 de La (Do) y traste 2 de Re (Mi).","Las figuras se pueden mover a cualquier tonalidad."],tips:["Toca el arpegio subiendo y bajando sobre cada acorde de una canción."]},lectura:{paragraphs:["En clave de Fa, una tríada en posición fundamental también se ve apilada en líneas o en espacios. Do mayor (Do–Mi–Sol) desde el Do del segundo espacio ocupa los espacios 2, 3 y 4.","En una partitura de bajo, las tríadas suelen aparecer arpegiadas (una nota tras otra)."],tips:["Escribe las tríadas de Do, Fa y Sol en clave de Fa."]},oido:a.s011}},"bajo-n2-l06":{status:"borrador",generated:!0,sections:{teoria:a.s135,practica:{paragraphs:["Cambiar de posición es mover la mano a otra zona del mástil. Para que suene limpio, prepara el cambio: mira hacia dónde vas, desliza la mano con el pulgar relajado y aprovecha una cuerda al aire o un slide.","Practica escalas que suban en una posición y bajen en otra."],tips:['Usa el dedo 1 como "guía": deslízalo por la cuerda hasta la nueva posición.']},lectura:a.s017,oido:a.s136}},"bajo-n2-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Una nota de paso conecta dos notas del acorde por grados o semitonos. En el bajo se usan para unir los cambios de acorde: por ejemplo, de Do a Fa puedes pasar por Re y Mi.","Las notas de paso cromáticas (de medio en medio tono) dan un sabor jazzístico o de blues."],tips:["Toca Do (3 tiempos) y una nota de paso en el 4º tiempo antes de llegar al siguiente acorde."]},practica:{paragraphs:["Toca una progresión (por ejemplo C – Am – F – G) usando la fundamental en los primeros tiempos y una nota de paso al final de cada compás que lleve al siguiente acorde.","Prueba notas de paso por escala (diatónicas) y por semitono (cromáticas)."],tips:["La nota de paso va casi siempre en el último tiempo del compás."]},lectura:a.s137,oido:{paragraphs:["Las notas del acorde suenan estables; las notas de paso suenan de movimiento, como si fueran hacia otro lugar.","Escucha y decide si la nota es del acorde o de paso."],tips:["Fíjate si la nota está en un tiempo fuerte (normalmente del acorde) o en uno débil."]}}},"bajo-n2-l08":{status:"borrador",generated:!0,sections:{teoria:a.s014,practica:{paragraphs:['Combinar corcheas y semicorcheas da movimiento a la línea de bajo. Un patrón común: corchea + dos semicorcheas ("1-y-a") sobre la fundamental.',"Practica alternando los dedos índice y medio de forma estricta para mantener el ritmo parejo."],tips:["Metrónomo a 70 BPM, una semana; luego sube."]},lectura:a.s015,oido:a.s016}},"bajo-n2-l09":{status:"borrador",generated:!0,sections:{teoria:a.s138,practica:{paragraphs:["Tu sonido depende de tus manos (dónde pulsas, con cuánta fuerza), del bajo (pastillas, tono, cuerdas) y del amplificador (ecualización). Pulsar cerca del puente da un sonido brillante y firme; cerca del mástil, uno gordo y suave.","Prueba ajustes distintos y anota los que te gustan para cada estilo."],tips:["Graba la misma línea con 3 sonidos distintos y escoge tu favorito."]},lectura:a.s021,oido:{paragraphs:["Un sonido grave y redondo tiene pocos agudos; uno brillante tiene más ataque y definición. Escucha y clasifica."],tips:["Escucha con audífonos para notar mejor los agudos."]}}},"bajo-n2-l10":{status:"borrador",generated:!0,sections:{teoria:a.s139,practica:{paragraphs:["La pentatónica menor es ideal para crear líneas de bajo y rellenos (fills) al final de las frases. En La menor: La–Do–Re–Mi–Sol.","Toca la fundamental durante 3 tiempos y usa el 4º para un pequeño relleno de 2 a 4 notas que regrese a la fundamental."],tips:["Usa los rellenos solo cada 2 o 4 compases para que no pierdan efecto."]},lectura:a.s140,oido:{paragraphs:["Un relleno es un pequeño adorno al final de una frase que rompe la repetición de la línea. Escucha una línea de bajo y levanta la mano cuando escuches un relleno."],tips:["Suelen aparecer en el compás 4 u 8 de una sección."]}}},"bajo-n2-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En el rock y el pop, el bajo suele tocar corcheas constantes sobre la fundamental, reforzando el bombo de la batería. También se usan patrones con negras y síncopas sencillas.","El objetivo es dar una base firme y pegada a la batería."],tips:["Escucha el bombo de la canción y trata de que tus notas coincidan con él."]},practica:{paragraphs:["Toca corcheas constantes sobre la fundamental de cada acorde con alternancia de dedos o plumilla. Agrega una quinta u octava para variar."],tips:["Mantén el volumen de todas las corcheas igual: eso es lo que da potencia."],tab:`G|---------------|
D|-------------5-|
A|-3-3-3-3-3-3---|
E|---------------|`},lectura:{paragraphs:["Una ligadura de prolongación une dos notas iguales para sumar su duración. Cuando la ligadura cruza el tiempo, crea una síncopa: el sonido empieza antes del pulso y sigue sonando sobre él.","Cuenta en voz alta y no vuelvas a tocar la nota ligada."],tips:["Aplaude el ritmo primero; después tócalo con una sola nota."]},oido:a.s022}},"bajo-n2-l12":{status:"borrador",generated:!0,sections:{teoria:a.s023,practica:{paragraphs:["Una línea de blues clásica usa fundamental, tercera, quinta, sexta y séptima menor del acorde, subiendo y bajando. En La: La–Do♯–Mi–Fa♯–Sol–Fa♯–Mi–Do♯.","Toca esa figura en cada acorde del blues (A7, D7, E7) siguiendo la forma de 12 compases."],tips:["Escucha cualquier blues clásico: notarás esta línea muchísimas veces."],tab:`G|---------------|
D|-----2-4-5-4-2-|
A|-0-4-----------|
E|---------------|`},lectura:a.s024,oido:a.s025}},"bajo-n3-l01":{status:"borrador",generated:!0,sections:{teoria:a.s028,practica:{paragraphs:['Los hammer-ons y pull-offs en el bajo suavizan las líneas y agregan "groove". Se usan mucho en funk, soul y en rellenos.',"Practica un hammer-on del traste 5 al 7 y un pull-off del 7 al 5 en la cuerda La, dentro de una línea sencilla."],tips:["En el bajo se necesita un poco más de fuerza que en la guitarra para que el ligado se escuche."]},lectura:a.s029,oido:a.s030}},"bajo-n3-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El slide desliza el dedo de una nota a otra sin dejar de presionar; da un efecto suave y fluido. La nota muerta (ghost note) es un golpe sin altura: tocas la cuerda mientras la mano izquierda la apaga.","Las notas muertas añaden ritmo y percusión, esenciales en el funk y el R&B."],tips:['Combina una nota real con una muerta: "pum-tk, pum-tk".']},practica:{paragraphs:["Crea una línea de 1 compás que use una nota real, un slide hacia la octava y notas muertas entre golpes. Repítela con metrónomo hasta que suene fluida."],tips:["La mano izquierda nunca suelta del todo: solo deja de presionar para la nota muerta."]},lectura:{paragraphs:['El slide se escribe con una diagonal entre notas (5/7) en tablatura o una línea recta en partitura. La nota muerta se escribe con una "x" en lugar del número o de la cabeza de nota.'],tips:["Lee una línea de funk escrita y señala todos los slides y notas muertas antes de tocarla."]},oido:{paragraphs:["La nota muerta suena como un golpe seco, sin nota definida. Escucha líneas de bajo y cuenta cuántas notas muertas hay."],tips:["Escucha funk: las notas muertas son parte del groove."]}}},"bajo-n3-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['El bajo y la batería forman la "sección rítmica": son la base sobre la que tocan los demás. El bajo suele coincidir con el bombo y llenar los espacios entre la tarola.',"Cuando bajo y batería están bien sincronizados, la banda suena sólida aunque los demás toquen poco."],tips:["Escucha canciones concentrándote solo en bajo y bombo: ¿cuándo coinciden?"]},practica:{paragraphs:["Toca la misma línea sencilla sobre distintos patrones de batería: rock, pop, funk, balada y shuffle. Ajusta tus notas para que coincidan con el bombo de cada patrón."],tips:["Usa la sección Ritmos de LML para practicar con distintos patrones."]},lectura:{paragraphs:["En la partitura de batería, el bombo va en el primer espacio, la tarola en el tercer espacio y el hi-hat arriba del pentagrama con cabeza en x. El patrón básico de rock tiene bombo en 1 y 3, tarola en 2 y 4 y hi-hat en corcheas.","Leer la batería te ayuda a saber dónde poner tus notas."],tips:["Marca con color las notas del bombo: ahí suele ir tu línea."]},oido:a.s141}},"bajo-n3-l04":{status:"borrador",generated:!0,sections:{teoria:a.s142,practica:{paragraphs:["Para aprender una línea de bajo con tablatura, escucha primero la canción y ubica el ritmo. Aprende la línea por secciones (verso, coro) y tócala con la grabación.","Fíjate en la duración de cada nota: en el bajo, cuánto dura una nota es tan importante como cuál nota es."],tips:["Baja la velocidad de la grabación para practicar las partes difíciles."]},lectura:a.s035,oido:{paragraphs:["Escucha la línea, cántala y busca la primera nota en el bajo (normalmente la fundamental del acorde). Después deduce las demás según si suben o bajan."],tips:["Las notas graves cuestan más: canta la línea una octava arriba si te ayuda."]}}},"bajo-n3-l05":{status:"borrador",generated:!0,sections:{teoria:a.s143,practica:{paragraphs:["Para crear tu línea, parte de las fundamentales de cada acorde y agrega quintas, octavas, notas de paso y rellenos. Ajusta el ritmo al patrón de la batería.","La mejor línea es la que sostiene la canción sin estorbar a la voz."],tips:["Escribe tu línea en tablatura y tócala sobre la grabación original."]},lectura:a.s144,oido:{paragraphs:["Muchas líneas de bajo se repiten varias veces (ostinato). Escucha una canción e identifica cuántas veces se repite la línea antes de cambiar."],tips:["Cuenta los compases de cada repetición."]}}},"bajo-n3-l06":{status:"borrador",generated:!0,sections:{teoria:a.s145,practica:{paragraphs:["El compresor iguala el volumen de las notas: las fuertes se suavizan y las suaves se escuchan más. El overdrive agrega saturación y presencia. El chorus engrosa el sonido con un ligero vaivén.","Usa el compresor casi siempre, el overdrive para rock y el chorus en partes melódicas o en baladas."],tips:['Ajusta el compresor para que apenas se note: si suena "aplastado", es demasiado.']},lectura:a.s146,oido:{paragraphs:["El compresor hace que las notas suenen parejas y con más sustain; el overdrive agrega un borde áspero al sonido.","Escucha y decide qué efecto se usa."],tips:['Fíjate en las notas fuertes: con compresor no "saltan" tanto.']}}},"bajo-n3-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La pentatónica menor tiene 5 posiciones que cubren todo el mástil. En el bajo, conocer varias posiciones permite tocar líneas en distintos registros y conectar rellenos sin saltos grandes.","En La menor, empieza por la posición del traste 5 y luego aprende la del traste 7-8."],tips:["Aprende una posición a la vez y únela con la anterior."]},practica:a.s147,lectura:a.s148,oido:a.s149}},"bajo-n3-l08":{status:"borrador",generated:!0,sections:{teoria:a.s032,practica:{paragraphs:["Toca una línea que ya conoces en otros tonos moviendo la misma figura a otra fundamental. Por ejemplo, una línea en La (traste 5 de Mi) se toca en Do moviéndola al traste 8, o en Re usando la cuerda La al aire como fundamental."],tips:["Practica con una pista que cambie de tono cada 8 compases."]},lectura:a.s033,oido:a.s034}},"bajo-n3-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['En el bajo, la duración de las notas cambia mucho el "feeling": notas largas (legato) dan un sonido lleno y suave; notas cortas (staccato) dan ritmo y espacio.',"La dinámica (fuerte o suave) también ayuda a construir la intensidad de la canción, por ejemplo tocando más suave en el verso y más fuerte en el coro."],tips:["Toca la misma línea con notas largas y luego cortas, y elige cuál le queda mejor a la canción."]},practica:{paragraphs:["Para acortar una nota, levanta ligeramente el dedo de la mano izquierda (sin soltar la cuerda del todo) o apoya un dedo de la derecha. Para alargarla, mantén la presión hasta la siguiente nota.","Practica una línea alternando una nota larga y una corta."],tips:["Escucha cómo la duración cambia el groove aunque las notas sean las mismas."]},lectura:{paragraphs:["Los matices (p, mf, f) indican el volumen. La articulación indica cómo atacar y cuánto dura cada nota: un punto encima es staccato (corta), una rayita es tenuto (sostenida) y > es acento."],tips:["Lee una línea con estos signos y exagera cada uno."]},oido:{paragraphs:["Escucha y decide si las notas suenan largas (sostenidas hasta la siguiente) o cortas (con silencio entre ellas)."],tips:['Imagina si "respiran" entre ellas: si hay espacio, son cortas.']}}},"bajo-n3-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Los rellenos (fills) son pequeñas frases que el bajo toca al final de una sección para anunciar la siguiente: del verso al coro, del coro al puente, etc.","Un buen relleno es corto y lleva claramente a la primera nota de la nueva sección."],tips:["Escucha cómo el baterista también hace un relleno al mismo tiempo: coordínate con él."]},practica:{paragraphs:["Practica una progresión de 4 compases: 3 compases de línea normal y en el 4º un relleno de 2 tiempos que termine en la fundamental del siguiente acorde.","Usa la pentatónica o notas de paso cromáticas."],tips:["Graba varias opciones de relleno y elige las que mejor conducen al coro."]},lectura:a.s038,oido:{paragraphs:["Canta la línea de bajo (puedes hacerlo una octava arriba) y luego tócala. Cantar conecta tu oído con tu instrumento y te ayuda a memorizar."],tips:["Empieza con líneas de 4 notas y aumenta poco a poco."]}}},"bajo-n3-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El bajo cumple dos funciones a la vez: rítmica (con la batería) y armónica (indicando qué acorde suena). Por eso es el puente entre la batería y los instrumentos melódicos.","Un bajista que escucha bien a la banda hace que todos suenen mejor."],tips:["Escucha cómo cambia la canción si quitas el bajo: la armonía se vuelve confusa."]},practica:{paragraphs:['Toca con pistas que tengan guitarra y batería. Coordina tus notas con el bombo y tus cambios de acorde con la guitarra. Evita tocar en el mismo registro que la guitarra para no "chocar".'],tips:["Mira o escucha al baterista para los cortes y finales."]},lectura:{paragraphs:['Una parte de bajo puede escribirse en partitura, tablatura o solo con cifrado y ritmo. Incluye la forma, los cortes, las entradas y a veces indicaciones como "walk" (caminante) o "sim." (similar).'],tips:["Repasa la forma completa antes de tocar con la banda."]},oido:a.s150}},"bajo-n3-l12":{status:"borrador",generated:!0,sections:{teoria:a.s040,practica:a.s041,lectura:{paragraphs:["Lee una línea de bajo con armadura (por ejemplo Sol mayor, con Fa♯). Antes de tocar revisa la clave de Fa, el compás, la armadura y las alteraciones accidentales."],tips:["Toca primero la escala de la tonalidad para orientar el oído."]},oido:{paragraphs:["Escucha una línea corta de bajo, cántala y encuéntrala en tu instrumento. Empieza buscando la nota más grave o la que se repite más (suele ser la fundamental)."],tips:["Usa audífonos con buenos graves."]}}},"bajo-n4-l01":{status:"borrador",generated:!0,sections:{teoria:a.s151,practica:{paragraphs:["Las líneas de funk combinan notas cortas, notas muertas, síncopas en semicorcheas, octavas y slides. El bajo es protagonista en el funk.","Empieza con un patrón sobre una sola nota (Mi): fundamental, nota muerta, octava, nota muerta, y agrega síncopas."],tips:["Metrónomo lento y semicorcheas contadas en voz alta."],tab:`G|-------------|
D|---2-----2---|
A|-------------|
E|-0---x-0---x-|`},lectura:a.s152,oido:a.s153}},"bajo-n4-l02":{status:"borrador",generated:!0,sections:{teoria:a.s044,practica:{paragraphs:["Toca líneas sobre una progresión I–IV–V (por ejemplo en La: A–D–E) usando fundamental, quinta y octava. Luego agrega terceras y notas de paso para conectar los acordes."],tips:["Practica la misma progresión en Do, Sol y Mi."]},lectura:a.s046,oido:a.s047}},"bajo-n4-l03":{status:"borrador",generated:!0,sections:{teoria:a.s048,practica:{paragraphs:["Cambiar de tonalidad (transportar) significa tocar la misma canción más aguda o más grave. Se hace moviendo todos los acordes la misma distancia.","Piensa la canción en grados (I, IV, V…) y tradúcela al nuevo tono. En el bajo, muchas figuras se pueden mover tal cual a otra posición."],tips:["Toca una canción que conozcas en su tono original y luego un tono más arriba."]},lectura:a.s049,oido:a.s050}},"bajo-n4-l04":{status:"borrador",generated:!0,sections:{teoria:a.s051,practica:{paragraphs:["Al analizar una línea de funk, identifica las notas del acorde, las notas muertas, los slides y la síncopa. Escríbela en tablatura con su ritmo exacto."],tips:["Toca la línea junto con la grabación hasta que encaje sin esfuerzo."]},lectura:a.s053,oido:a.s054}},"bajo-n4-l05":{status:"borrador",generated:!0,sections:{teoria:a.s059,practica:{paragraphs:["Las notas del acorde con séptima (1, 3, 5 y 7) dan líneas más ricas que solo fundamental y quinta. En C7: Do–Mi–Sol–Si♭; en Am7: La–Do–Mi–Sol.","Toca líneas que recorran esas notas en distintos órdenes."],tips:["Escucha cómo la séptima le da un sabor de blues o jazz a la línea."]},lectura:a.s154,oido:a.s155}},"bajo-n4-l06":{status:"borrador",generated:!0,sections:{teoria:a.s156,practica:{paragraphs:["Toca los arpegios de la escala armonizada (I, IIm, IIIm, IV, V, VIm, VII°) en una tonalidad y luego muévelos a otras. Las figuras se mantienen: solo cambia el punto de partida."],tips:["Practica en Do, Sol y Fa."]},lectura:a.s061,oido:a.s157}},"bajo-n4-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Para componer una línea, parte de la progresión y el ritmo de la batería. Define un motivo rítmico que se repita y elige las notas: fundamentales en tiempos fuertes, y quintas, octavas o notas de paso en los débiles.","Varía la línea entre secciones: más simple en el verso, más activa en el coro."],tips:["Graba la batería o usa una pista y crea la línea sobre ella."]},practica:a.s158,lectura:{paragraphs:["Escribe la progresión con cifrado arriba de los compases y, debajo, la línea de bajo en tablatura o clave de Fa. Indica el ritmo con figuras."],tips:["Revisa que la primera nota de cada compás coincida con la fundamental del acorde."]},oido:a.s062}},"bajo-n4-l08":{status:"borrador",generated:!0,sections:{teoria:a.s159,practica:{paragraphs:["Practica arpegios de cuatro notas: maj7 (1–3–5–7), m7 (1–♭3–5–♭7) y 7 (1–3–5–♭7). Ejemplos: Cmaj7 (Do–Mi–Sol–Si), Cm7 (Do–Mi♭–Sol–Si♭) y C7 (Do–Mi–Sol–Si♭).","Úsalos para crear líneas en baladas, soul y jazz."],tips:["Toca cada arpegio subiendo y bajando, diciendo el grado de cada nota."]},lectura:a.s003,oido:a.s160}},"bajo-n4-l09":{status:"borrador",generated:!0,sections:{teoria:a.s161,practica:{paragraphs:["Una línea que cambia según la sección ayuda a construir la canción. En el verso, toca notas largas o un patrón sencillo; en el coro, más movimiento, octavas o un ritmo más intenso."],tips:["Escucha cómo los bajistas de tus canciones favoritas cambian entre verso y coro."]},lectura:a.s065,oido:a.s066}},"bajo-n4-l10":{status:"borrador",generated:!0,sections:{teoria:a.s162,practica:a.s163,lectura:a.s164,oido:a.s165}},"bajo-n4-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El slap es una técnica percusiva: el pulgar golpea la cuerda (thumb) contra el último traste y los dedos índice o medio la jalan (pop) para que rebote contra el diapasón.","Nació en el funk de los 70 con Larry Graham y se popularizó con Marcus Miller, Flea y Victor Wooten."],tips:["Empieza golpeando con el pulgar solo la cuerda Mi al aire, con el antebrazo relajado."]},practica:{paragraphs:["El patrón básico de slap alterna un golpe de pulgar en una nota grave y un jalón en la octava. Por ejemplo, pulgar en Mi al aire y jalón en el traste 2 de la cuerda Re.","Gira la muñeca como si sacudieras agua de la mano: el pulgar rebota en la cuerda."],tips:["Practica lento: el slap pide precisión antes que velocidad."],tab:`G|-----------|
D|---2---2---|
A|-----------|
E|-0---0-----|
(T P T P)`},lectura:{paragraphs:["En la notación de slap, se usa T (thumb, pulgar) y P (pop, jalón) debajo de las notas. Las notas muertas golpeadas se escriben con x."],tips:['Lee una línea de slap y pronuncia "T" y "P" en voz alta antes de tocarla.']},oido:{paragraphs:["El slap suena percusivo y brillante, con un ataque fuerte; la pulsación con dedos es más redonda y suave.","Escucha y decide qué técnica se usa."],tips:["El jalón (pop) suena como un chasquido agudo."]}}},"bajo-n4-l12":{status:"borrador",generated:!0,sections:{teoria:a.s067,practica:{paragraphs:["Elige un género que te guste y estudia sus tres pilares en el bajo: el patrón rítmico típico, las progresiones o acordes característicos y el tipo de sonido (limpio, saturado, con efectos o acústico).","Practica cada pilar por separado y luego toca una canción completa del género."],tips:["Escucha la canción con atención antes de tocarla: copiar el sonido es parte del estudio."]},lectura:a.s068,oido:a.s069}},"bajo-n5-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En el rock y el metal, el bajo suele reforzar los riffs de la guitarra y el bombo de la batería, muchas veces con plumilla y saturación. En el metal es común el galope y las notas rápidas en corcheas o semicorcheas.","Bajistas de referencia: Geddy Lee (Rush), Steve Harris (Iron Maiden), Cliff Burton (Metallica)."],tips:["Escucha cómo el bajo y la guitarra tocan el mismo riff para sonar más potente."]},practica:{paragraphs:['El galope es un ritmo de corchea + dos semicorcheas ("ta-taka"), muy usado en el metal. Con plumilla, se toca abajo–abajo–arriba o con púa alternada.',"Practica en una sola nota y luego en un riff."],tips:["Mantén la muñeca relajada; la tensión limita la velocidad."]},lectura:{paragraphs:["Para leer corcheas rápidas, agrupa de a dos por tiempo y busca patrones repetidos. Lee con metrónomo a velocidad lenta y súbela poco a poco."],tips:["Marca el pulso con el pie mientras lees."]},oido:{paragraphs:['El galope suena como un caballo trotando: "ta-taka, ta-taka". Escucha fragmentos e identifica si hay galope.'],tips:["Busca en canciones de Iron Maiden: es su marca."]}}},"bajo-n5-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Motown fue un sello de Detroit de los 60 y 70 (The Supremes, Stevie Wonder, Marvin Gaye). Su bajista, James Jamerson, creó líneas melódicas, sincopadas y llenas de notas cromáticas que se volvieron el estándar del bajo moderno.","El soul se caracteriza por grooves profundos, líneas que dialogan con la voz y mucha expresividad."],tips:[`Escucha "What's Going On" o "Bernadette" y sigue solo el bajo.`]},practica:{paragraphs:['Las líneas de soul combinan notas del acorde, notas de paso cromáticas y síncopas. En lugar de repetir la fundamental, la línea "canta" entre los cambios de acorde.',"Practica una línea de 2 compases que use corcheas sincopadas y una nota de paso cromática."],tips:["La síncopa debe sentirse relajada, no apurada."]},lectura:{paragraphs:["Las síncopas se escriben con ligaduras que unen una nota de la parte débil con la siguiente parte fuerte. Cuenta siempre la subdivisión completa."],tips:['Lee la síncopa diciendo "1 y (2) y" donde el paréntesis es la nota ligada.']},oido:a.s166}},"bajo-n5-l03":{status:"borrador",generated:!0,sections:{teoria:a.s167,practica:{paragraphs:["El bajo caminante (walking bass) es típico del jazz y el blues: toca una nota por tiempo, caminando entre los acordes. Usa fundamentales en el tiempo 1, notas del acorde y notas de paso que lleven al siguiente acorde.","Ejemplo sobre C7 a F7: Do–Mi–Sol–Mi | Fa…"],tips:["Toca negras constantes con metrónomo en el 2 y el 4 para sentir el swing."]},lectura:{paragraphs:["Un bajo caminante escrito tiene negras constantes con alteraciones frecuentes (notas cromáticas). Lee identificando el acorde de cada compás y cómo la línea llega al siguiente."],tips:["Marca la primera nota de cada compás: casi siempre es la fundamental."]},oido:{paragraphs:['Escucha una progresión con bajo caminante y di "cambio" cada vez que cambie el acorde. El bajo suele llegar a la fundamental justo en el cambio.'],tips:["Escucha jazz y blues: el bajo te dice siempre dónde está la armonía."]}}},"bajo-n5-l04":{status:"borrador",generated:!0,sections:{teoria:a.s168,practica:{paragraphs:['El tumbao es el patrón del bajo en la salsa: anticipa la armonía tocando en el "y" del 2 y en el 4, dejando el 1 en silencio. Suele usar la fundamental y la quinta.','Sobre C: silencio en 1, Do en el "y" del 2, Sol en el 4 (que se liga al siguiente compás).'],tips:['Escucha salsa y marca dónde entra el bajo: casi nunca en el "uno".']},lectura:a.s058,oido:a.s169}},"bajo-n5-l05":{status:"borrador",generated:!0,sections:{teoria:a.s071,practica:a.s170,lectura:a.s072,oido:a.s073}},"bajo-n5-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['En el slap avanzado se combinan golpes de pulgar, jalones, notas muertas, hammer-ons y golpes de mano izquierda (left-hand slap). También se usan "double thumbing" (pulgar hacia abajo y hacia arriba) y octavas rápidas.'],tips:["Practica cada técnica por separado antes de unirlas."]},practica:{paragraphs:["Una línea de slap con notas muertas alterna golpes reales y percusivos: T (nota), T muerta, P (octava), T muerta. Las notas muertas dan el ritmo continuo."],tips:["Practica a 70 BPM en semicorcheas y sube gradualmente."]},lectura:{paragraphs:["Lee la línea identificando qué notas van con pulgar (T) y cuáles con jalón (P), y dónde hay notas muertas (x). El ritmo suele estar en semicorcheas."],tips:["Toca primero solo las T, luego solo las P, y luego juntas."]},oido:{paragraphs:["El golpe de pulgar suena grave y percusivo; el jalón, agudo y como un chasquido. Escucha y clasifica cada golpe."],tips:["Fíjate en el registro: el pulgar suele ir en las cuerdas graves."]}}},"bajo-n5-l07":{status:"borrador",generated:!0,sections:{teoria:a.s075,practica:a.s076,lectura:a.s077,oido:a.s078}},"bajo-n5-l08":{status:"borrador",generated:!0,sections:{teoria:a.s079,practica:{paragraphs:["Sobre Dm7 – G7 – Cmaj7, toca la fundamental de cada acorde en el tiempo 1 y conecta con notas del acorde y notas de paso. Ejemplo: Re–Fa–La–La♭ | Sol–Si–Re–Si | Do… (el La♭ y el Si son notas de acercamiento)"],tips:["Practica en Do, Fa y Sol."]},lectura:a.s087,oido:a.s088}},"bajo-n5-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La velocidad se construye con precisión y relajación, no con fuerza. Practica con metrónomo, subiendo 4 o 5 BPM solo cuando el pasaje salga limpio varias veces.","La resistencia se gana con sesiones cortas y frecuentes. Si sientes dolor, detente y descansa."],tips:["Estira las manos antes y después de practicar."]},practica:{paragraphs:["Toca semicorcheas continuas en una nota, alternando dedos estrictamente (índice–medio). Empieza a 60 BPM y sube 5 BPM por día solo si sale parejo.","Después aplica el ejercicio a una escala o una línea."],tips:["Graba y escucha: todas las notas deben sonar con el mismo volumen."]},lectura:a.s084,oido:{paragraphs:["Para transcribir una línea de bajo, escucha y canta; identifica la fundamental de cada acorde y luego las notas intermedias. Escribe en tablatura o clave de Fa con el ritmo."],tips:["Baja la velocidad de la grabación y usa audífonos."]}}},"bajo-n5-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Aunque el bajo suele tocar una nota a la vez, también puede tocar acordes de dos o tres notas, sobre todo en registros medios y agudos. Las décimas (fundamental + tercera una octava arriba) suenan muy bien en el bajo.","Se usan en baladas, intros y piezas para bajo solo."],tips:["Evita acordes cerrados en el registro grave: suenan confusos."]},practica:{paragraphs:["Una décima es una tercera más una octava: por ejemplo, Do en la cuerda La (traste 3) y Mi en la cuerda Sol (traste 9). Toca ambas notas a la vez con el pulgar y un dedo.","Practica décimas mayores y menores sobre una progresión."],tips:["Toca las décimas suavemente y deja que suenen."]},lectura:{paragraphs:["Cuando dos notas suenan juntas, en la partitura se escriben una encima de la otra en la misma plica. En la tablatura, los dos números van en la misma columna."],tips:["Lee primero la nota de abajo y luego la de arriba."]},oido:a.s171}},"bajo-n5-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El bajo también puede tocar melodías y solos. En registros altos suena cálido y expresivo. Bajistas como Jaco Pastorius o Victor Wooten lo han llevado al papel de solista.","Para tocar una melodía, usa la zona aguda del mástil y la pastilla del puente para más definición."],tips:["Toca la melodía de una canción conocida en las cuerdas agudas del bajo."]},practica:{paragraphs:["Aprende la melodía de una canción sencilla en el bajo y luego improvisa un solo corto de 8 compases con la pentatónica. Usa frases cortas y silencios."],tips:["Graba una pista de acordes para practicar sobre ella."]},lectura:a.s092,oido:a.s093}},"bajo-n5-l12":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En el arreglo de una canción, el bajo cambia según la sección: más sencillo en el verso, más activo en el coro y distinto en el puente para dar contraste.","Conocer la forma te ayuda a planear tu línea y tus rellenos."],tips:["Escribe la forma de una canción y anota qué hace el bajo en cada parte."]},practica:{paragraphs:["Crea una maqueta de 1 minuto: programa una batería sencilla, graba los acordes (con guitarra, teclado o en el DAW) y graba tu línea de bajo encima.","Usa una forma sencilla: introducción, verso y coro."],tips:["Lo importante es terminarla: después podrás mejorarla."]},lectura:a.s095,oido:a.s096}},"bajo-n6-l01":{status:"borrador",generated:!0,sections:{teoria:a.s097,practica:{paragraphs:["Antes de empezar el proyecto final, repasa lo más importante del curso en el bajo: técnica, acordes, escalas, ritmos y las canciones que ya sabes. Detecta qué te cuesta y dedica tiempo extra a eso.","Arma una rutina de 20 minutos: 5 de calentamiento, 10 de técnica y 5 de una canción."],tips:["Haz una lista de los temas que dominas y los que necesitas reforzar."]},lectura:a.s098,oido:a.s099}},"bajo-n6-l02":{status:"borrador",generated:!0,sections:{teoria:a.s172,practica:a.s173,lectura:a.s100,oido:a.s101}},"bajo-n6-l03":{status:"borrador",generated:!0,sections:{teoria:a.s102,practica:a.s103,lectura:a.s104,oido:a.s105}},"bajo-n6-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En la mezcla, el bajo y el bombo comparten los graves. Para que ambos se escuchen, se reparte el espacio: por ejemplo, el bombo ocupa los graves más profundos y el bajo un poco más arriba, o al revés.","El bajo debe sentirse en audífonos y bocinas pequeñas: los medios ayudan a que se escuche."],tips:["Escucha tu mezcla en el celular: si desaparece el bajo, súbele un poco de medios."]},practica:{paragraphs:["Graba el bajo escuchando una guía (batería y acordes, o una pista de referencia). Conecta el bajo directo a la interfaz (entrada Hi-Z) y ajusta la ganancia para que no sature.","Graba varias tomas y elige la más precisa."],tips:["Grabar en directo (DI) te permite cambiar el sonido después con plugins."]},lectura:a.s106,oido:a.s107}},"bajo-n6-l05":{status:"borrador",generated:!0,sections:{teoria:a.s108,practica:a.s109,lectura:a.s110,oido:a.s111}},"bajo-n6-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Programa en el DAW una batería y los acordes de tu canción como base para grabar el bajo. Usa el piano roll para los acordes y un patrón de batería sencillo."],tips:["Ajusta la velocidad (velocity) de algunos golpes para que la batería suene natural."]},practica:{paragraphs:["La base de una canción es la parte rítmica y armónica: batería (o metrónomo), bajo y los acordes de el bajo. Sobre ella se construyen la melodía y los demás arreglos.","Graba o programa primero una base sencilla y estable con la forma completa. Después ajusta los detalles de cada sección."],tips:["Revisa que la base suene bien sola, sin melodía: si funciona así, funcionará con todo."]},lectura:a.s174,oido:a.s175}},"bajo-n6-l07":{status:"borrador",generated:!0,sections:{teoria:a.s112,practica:a.s113,lectura:a.s114,oido:a.s115}},"bajo-n6-l08":{status:"borrador",generated:!0,sections:{teoria:a.s116,practica:{paragraphs:["Graba el bajo de tu proyecto final con la mejor toma posible. Mantén el mismo sonido en todas las secciones y cuida la afinación antes de cada toma."],tips:["Revisa en el DAW que las notas estén a tiempo con el bombo."]},lectura:a.s117,oido:{paragraphs:["El bajo y el bombo deben sonar juntos sin taparse. Escucha mezclas y decide si alguno está demasiado fuerte o si se confunden."],tips:["Escucha a bajo volumen: si ya no distingues el bajo, está muy bajo o le faltan medios."]}}},"bajo-n6-l09":{status:"borrador",generated:!0,sections:{teoria:a.s118,practica:a.s119,lectura:a.s120,oido:a.s121}},"bajo-n6-l10":{status:"borrador",generated:!0,sections:{teoria:a.s122,practica:{paragraphs:["Tocar en vivo es diferente a tocar en casa: hay nervios, otro volumen y menos control. Practica tocar la canción completa sin detenerte, mirando poco tu bajo y mirando más al público o a la banda.","Cuida el volumen, la afinación entre canciones y la energía en el escenario."],tips:["Ensaya las primeras notas de cada canción: si empiezas bien, el resto fluye."]},lectura:a.s124,oido:a.s125}},"bajo-n6-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En vivo, la señal del bajo va: bajo → afinador → pedales (compresor, overdrive, chorus) → amplificador → caja directa (DI) o micrófono → consola → bocinas y monitores.","Muchas veces se envía la señal de la DI directo a la consola para un sonido limpio y controlado."],tips:["Pide en el monitor el bombo y la voz para mantenerte a tiempo y en la forma."]},practica:a.s126,lectura:a.s127,oido:a.s128}},"bajo-n6-l12":{status:"borrador",generated:!0,sections:{teoria:a.s129,practica:{paragraphs:["Repasa las técnicas principales del curso en el bajo, del nivel 1 al 6, con metrónomo. Detecta las que ya dominas y las que necesitas seguir practicando.","Organiza una rutina de mantenimiento para después del curso: técnica, repertorio y creación."],tips:["Grábate tocando una pieza de cada nivel: verás todo lo que has avanzado."]},lectura:a.s130,oido:a.s131}}},c={...n,...r};export{c as CONTENT};
